import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  // Root container
  const container = new Group();

  // Keep track of active timelines and primitive handles for cleanup
  const activeTimelines = [];
  const primitiveHandles = [];

  // Color Palette
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. STAGE BACKDROP (Dark gradient to prevent void)
  const backdropGeo = new PlaneGeometry(12, 10);
  const backdropMat = new MeshBasicNodeMaterial();
  // Simple vertical gradient in TSL
  const uvCoords = uv();
  const topColor = color(colors.ink);
  const bottomColor = color(colors.surface);
  backdropMat.colorNode = mix(bottomColor, topColor, uvCoords.y);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(2.5, -1.6, -2.5); // Counter-adjust positional offset to keep stage centered
  container.add(backdrop);

  // 2. CONTACT SHADOW
  const shadowGeo = new PlaneGeometry(3, 2.2);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.05, -0.1);
  container.add(shadowPlane);

  // 3. MACHINED CARD BASE (Interactive element)
  const cardGeo = new BoxGeometry(2.6, 1.8, 0.1);
  const cardMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.25
  });
  const card = new Mesh(cardGeo, cardMat);
  container.add(card);

  // Accent edge border (engineered thin accent bar)
  const accentBarGeo = new BoxGeometry(0.08, 1.6, 0.12);
  const accentBarMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    roughness: 0.2,
    metalness: 0.8,
    emissive: colors.accent,
    emissiveIntensity: 0.8
  });
  const accentBar = new Mesh(accentBarGeo, accentBarMat);
  accentBar.position.set(-1.2, 0, 0);
  card.add(accentBar);

  // 4. LIGHTS (Local studio lighting rig)
  const localKeyLight = new DirectionalLight(colors.paper, 1.2);
  localKeyLight.position.set(2, 3, 4);
  container.add(localKeyLight);

  const localRimLight = new DirectionalLight(colors.accent, 0.8);
  localRimLight.position.set(-3, -2, 2);
  container.add(localRimLight);

  // 5. HERO GLB MESH (The gear)
  let gearMesh = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gearMesh = gltf.scene;

      // Auto-scale and set materials to fit the metallic aesthetic
      gearMesh.scale.setScalar(0.7);
      gearMesh.position.set(0.6, 0, 0.15);
      gearMesh.rotation.x = Math.PI / 2;

      gearMesh.traverse((child) => {
        if (child.isMesh) {
          child.material = new MeshStandardNodeMaterial({
            color: colors.paper,
            metalness: 0.95,
            roughness: 0.1,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1
          });
        }
      });

      card.add(gearMesh);

      // Slow rotational heartbeat anim
      const rotTl = gsap.timeline({ repeat: -1 });
      rotTl.to(gearMesh.rotation, {
        y: Math.PI * 2,
        duration: 16,
        ease: 'none'
      });
      activeTimelines.push(rotTl);
    }).catch(err => console.error('Failed to load gear GLB', err));
  }

  // 6. TYPOGRAPHY / LABELS (Text metrics from binding metadata)
  const valueText = ctx.fontAtlas.createText('01', {
    fontSize: 0.5,
    color: colors.paper,
    align: 'left'
  });
  valueText.position.set(-0.9, 0.1, 0.08);
  card.add(valueText);

  const labelText = ctx.fontAtlas.createText('CHRONO TIER', {
    fontSize: 0.1,
    color: colors.paper,
    align: 'left'
  });
  labelText.position.set(-0.9, -0.4, 0.08);
  card.add(labelText);

  // 7. BEHAVIORS & INTERACTIVITY
  // Interactive handlers bound to card's userData
  card.userData.handlers = {
    pointerover: () => {
      // Subtle rise-in lift effect
      gsap.to(card.position, {
        z: 0.15,
        y: 0.05,
        duration: 0.3,
        ease: 'power2.out'
      });
      // Emphasize rim/accent light slightly
      gsap.to(localRimLight, {
        intensity: 1.4,
        duration: 0.3
      });
    },
    pointerout: () => {
      // Settle down
      gsap.to(card.position, {
        z: 0,
        y: 0,
        duration: 0.4,
        ease: 'power3.out'
      });
      gsap.to(localRimLight, {
        intensity: 0.8,
        duration: 0.4
      });
    },
    click: () => {
      // Direct click transition
      const clickTl = gsap.timeline();
      clickTl.to(card.scale, { x: 0.96, y: 0.96, z: 0.96, duration: 0.1, ease: 'power2.out' })
             .to(card.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out(2)' });

      activeTimelines.push(clickTl);

      // Emit navigation trigger
      ctx.emit('hub-home.select', { tier: '01' });
    }
  };

  // 8. APPLY CINEMATIC PRIMITIVES
  const primitivesList = config.cinematicPrimitives ?? [
    { name: 'parallax-scroll', params: { intensity: 0.25 }, trigger: 'scroll' }
  ];

  for (const prim of primitivesList) {
    if (ctx.primitives[prim.name]) {
      const handle = ctx.primitives[prim.name](container, prim.params);
      if (handle) {
        primitiveHandles.push(handle);
      }
    }
  }

  // 9. CLEANUP METHOD
  container.userData.cleanup = () => {
    // Kill GSAP timelines
    activeTimelines.forEach((tl) => tl.kill());
    // Cleanup cinematic primitives
    primitiveHandles.forEach((h) => {
      if (typeof h.cleanup === 'function') h.cleanup();
    });
    // Traverse and dispose materials and geometries
    container.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  return container;
}
